async function render(){
 const ticket=++renderId,raw=location.hash.slice(1)||'home',[baseQuery,paramQuery]=raw.split('/'),[base]=baseQuery.split('?'),param=paramQuery?.split('?')[0];
 cleanupLyricsEditor();cleanupSing();
 $('.sidebar').classList.remove('open');updateBrowseNavigation(base,param);
 $('#main').setAttribute('aria-busy','true');let html='';
 try{
  if(base==='home')return await renderHome(ticket);
  await accountReady;if(ticket!==renderId)return;
  const explorer=await browseView(base,param,raw)||await explorerView(base,param,raw);
  if(explorer){html=explorer.html;routeTracks=remember(explorer.tracks||[]);}
  else if(['discover','charts','artists','producers','search'].includes(base)){
   let query='';const genre=base==='discover'?decodeURIComponent(param||'전체'):'전체',searchValue=base==='search'?decodeURIComponent(param||''):'';
   if(base==='charts')query='?chart='+({rising:'rising',newcomers:'newcomers',releases:'releases'}[param]||'top');
   if(base==='discover'&&genre!=='전체')query='?genre='+encodeURIComponent(genre);
   if(base==='search')query='?q='+encodeURIComponent(searchValue);
   const data=await api('/api/catalog'+query);routeTracks=remember(data.tracks);
   if(base==='discover')html=heading('음악 발견','장르를 넘나들며 새로운 취향을 찾아보세요.')+`<div class="genre-chips">${genres.map(g=>`<a class="genre-chip ${g===genre?'active':''}" href="#discover/${encodeURIComponent(g)}">${g}</a>`).join('')}</div>`+grid(data.tracks);
   else if(base==='charts')html=heading('AIFECT 차트','실제 감상과 좋아요·댓글로 함께 만드는 차트입니다.')+chartTabs(param||'')+list(data.tracks);
   else if(base==='artists'||base==='producers')html=heading(base==='artists'?'AI 아티스트':'제작자',base==='artists'?'새로운 목소리, 새로운 세계.':'당신이 좋아하는 음악을 만드는 사람들.')+identityCards(data[base],base==='artists'?'artist':'producer');
   else html=heading('음악 검색')+`<form id="search-form" class="aifect-search">${icon('search')}<input name="q" aria-label="곡, 아티스트, 제작자 검색" placeholder="곡, 아티스트, 제작자, 태그" value="${esc(searchValue)}" maxlength="100"><button class="primary-button">검색</button></form><p class="search-caption">${searchValue?`“${esc(searchValue)}” 검색 결과 ${data.tracks.length}곡`:'어떤 음악을 찾고 계신가요?'}</p>`+list(data.tracks);
  }else if(base==='song'){
   const {track:t}=await api('/api/tracks/'+param);remember([t]);const {comments}=await api(`/api/tracks/${param}/comments`);routeTracks=[t];
   const coverSort=new URLSearchParams(paramQuery?.split('?')[1]||'').get('covers')||'popular',coverData=t.kind==='original'?await api(`/api/tracks/${param}/covers?sort=${encodeURIComponent(coverSort)}`):null;if(coverData)remember(coverData.covers);const giftData=await api(`/api/tracks/${param}/gifts`);
   html=heading('곡 이야기')+`<section class="song-detail">${cover(t)}<div><span class="eyebrow">${esc(t.genre)} · ${time(t.duration)}</span><h2>${esc(t.title)}</h2>${songCredits(t)}<p class="song-description">${esc(t.description||'음악을 듣고 감상을 나눠보세요.')}</p><div class="inline-actions"><button class="primary-button" data-play="${t.id}">${icon('play')} ${me?'전체곡 듣기':'60초 미리 듣기'}</button>${t.karaoke_ready?`<a class="primary-button" href="#${inApp?'sing/'+t.id:'karaoke'}">${icon('mic')} ${inApp?'노래 부르기':'노래방에서 만나기'}</a>`:''}<button class="small-button ${liked(t.id)?'is-active':''}" data-like="${t.id}" aria-label="좋아요 ${number(t.likes)}개" aria-pressed="${liked(t.id)}">${icon('heart')} <span data-like-count>${number(t.likes)}</span></button><button class="small-button" data-add="${t.id}">${icon('plus')} 저장</button>${me?.id===t.user_id?'':`<button class="small-button" data-gift="${t.id}">${icon('sparkles')} 선물하기</button>`}</div><p class="song-metrics">${number(t.plays)}회 감상 · ${number(t.comments)}개 댓글</p></div></section>${lyricsPanel(t)}${coversPanelHTML(t,coverData,coverSort)}${giftsPanelHTML(giftData,'선물 순위')}<div class="song-columns"><section class="surface comments-panel"><div class="section-heading"><h2>함께 듣는 이야기</h2><select id="comment-sort" aria-label="댓글 정렬"><option value="latest">최신순</option><option value="popular">인기순</option><option value="timeline">타임라인순</option></select></div><form id="comment-form"><textarea name="body" maxlength="2000" required placeholder="${me?'이 곡의 어떤 순간이 좋았나요?':'로그인 후 감상을 남겨보세요.'}" aria-label="댓글"></textarea><div class="comment-compose-bottom"><label><input name="with_time" type="checkbox" checked> 현재 재생 시간 포함</label><button class="primary-button">댓글 등록</button></div><p class="form-error" role="alert"></p></form><div id="comments">${commentsHTML(comments,t)}</div></section><aside class="song-sidebar"><section class="surface"><h3>이 음악의 크레딧</h3><dl class="production-info"><dt>AI 도구</dt><dd>${esc(t.ai_tool)}</dd><dt>사람의 참여</dt><dd>${esc(t.participation||'—')}</dd><dt>장르</dt><dd>${esc(t.genre)}</dd><dt>태그</dt><dd>${esc(t.tags||'—')}</dd></dl></section></aside></div>`;
  }else if(base==='artist'||base==='producer'){
   const d=await api(`/api/${base==='artist'?'artists':'producers'}/${param}`);routeTracks=remember(d.tracks);
   if(base==='producer'){const q=new URLSearchParams(paramQuery?.split('?')[1]||''),tab=q.get('tab')==='covers'||(q.get('tab')!=='tracks'&&!d.tracks.length&&d.covers.length)?'covers':'tracks';remember(d.covers);routeTracks=tab==='covers'?d.covers:d.tracks;html=heading('프로필')+personProfileHTML(d,param,tab);}
   else html=heading(base==='artist'?'AI 아티스트':'제작자')+`<section class="profile-hero surface">${portrait(d.profile,base)}<div><span class="eyebrow">${base==='artist'?'AI ARTIST':'PRODUCER'}</span><h2>${esc(d.profile.name)}</h2><p>${esc(d.profile.bio||'새로운 음악으로 만나요.')}</p><div class="inline-actions"><span>${number(d.followers)} 팔로워 · ${d.tracks.length}곡</span><button class="primary-button" data-follow="${base}/${param}">${followed(base,param)?'팔로잉':'팔로우'}</button></div></div></section>`+section('공개한 음악')+list(d.tracks);
  }else if(['library','history','studio','upload','manage','cover','gold','admin','sing'].includes(base)&&!me){returnRoute=location.hash;html=gate();}
  else if(base==='library'){
   await refreshLibrary();const tab=param||'likes';routeTracks=library.likes;
   html=heading('내 보관함','좋아하는 음악과 창작자를 한곳에서.')+`<div class="tabs">${[['likes','좋아요'],['playlists','플레이리스트'],['artists','아티스트'],['producers','제작자']].map(([k,v])=>`<a class="tab ${tab===k?'active':''}" href="#library/${k}">${v}</a>`).join('')}</div>`;
   if(tab==='playlists')html+=`<div class="playlist-actions"><button class="primary-button" id="new-playlist">${icon('plus')} 플레이리스트 만들기</button></div>`+playlistsHTML(library.playlists);
   else if(tab==='artists'||tab==='producers')html+=identityCards(library.follows.filter(f=>f.kind===(tab==='artists'?'artist':'producer')).map(f=>({...f,id:f.target_id})),tab==='artists'?'artist':'producer');
   else html+=`<div class="inline-actions playlist-actions"><button class="primary-button" data-organize-likes ${library.likes.length?'':'disabled'}>좋아요한 곡으로 플레이리스트 만들기 ${icon('plus')}</button><span class="field-help">우울할 때, 기분 업… 기분에 맞게 모아보세요.</span></div>`+list(library.likes);
  }else if(base==='history'){const d=await api('/api/history');routeTracks=remember(d.tracks);html=heading('최근 들은 음악','다시 듣고 싶은 순간을 찾아보세요.')+list(d.tracks);}
  else if(base==='playlist'){
   const d=await api('/api/playlists/'+param);routeTracks=remember(d.tracks);const owned=me?.id===d.playlist.user_id;
   html=heading(esc(d.playlist.name),`${d.tracks.length}곡 · ${d.playlist.is_public?'공개 플레이리스트':'나만 보는 플레이리스트'}`)+`<div class="inline-actions playlist-actions"><button class="primary-button" data-play-all>전체 재생 ${icon('play')}</button>${owned?`<button class="small-button" data-pick-playlist="${param}">좋아요한 곡 담기</button><button class="small-button" data-order-playlist="${param}">곡 순서 편집</button><button class="small-button" data-edit-playlist="${param}">이름 · 공개 설정</button><button class="small-button" data-delete-playlist="${param}">삭제</button>`:''}${d.playlist.is_public?`<button class="small-button" data-share>링크 복사</button>`:''}</div>`+list(d.tracks,owned?param:null);
  }else if(base==='account')html=accountHTML();
  else if(base==='upload'){studioData=await api('/api/studio');html=uploadHTML(studioData);}
  else if(base==='karaoke'){const d=await api('/api/karaoke');routeTracks=d.tracks;html=karaokeListHTML(d.tracks);}
  else if(base==='sing'){routeSing=await api('/api/karaoke/'+param);html=singHTML(routeSing);}
  else if(base==='cover'){const {track:o}=await api('/api/tracks/'+param);remember([o]);html=coverUploadHTML(o);}
  else if(base==='gold')html=goldHTML(await api('/api/gold'));
  else if(base==='admin')html=adminHTML(await api('/api/admin/payouts'+(param?'?period='+encodeURIComponent(param):'')));
  else if(base==='manage'&&param){studioData=await api('/api/studio');const {profile,alignment,karaoke}=await api('/api/studio/tracks/'+param);html=profile.kind==='cover'?coverEditHTML(profile):trackEditHTML({...profile,alignment,karaoke},studioData);}
  else if(base==='studio'||base==='manage'){
   const d=await api('/api/studio');
   studioData=d;html=studioHTML(d)+earningsHTML(await api('/api/studio/earnings'));
  }else html=heading('페이지를 찾을 수 없어요')+empty('잠시 길을 잃었네요','홈에서 새로운 음악을 발견해보세요.','#home','홈으로 이동');
  if(ticket!==renderId)return;
  $('#main').innerHTML=html;$('#main').removeAttribute('aria-busy');if(typeof AifectMotion!=='undefined')AifectMotion.enter($('#main'),base+'/'+(param||''));icons();bindForms(base,param);bindExplorer(explorer);bindBrowse(explorer);window.scrollTo({top:0,behavior:'instant'});if(base==='song'&&paramQuery?.includes('comments=1'))$('.comments-panel')?.scrollIntoView({block:'start'});
 }catch(e){if(ticket!==renderId)return;$('#main').innerHTML=heading('다시 연결해주세요')+`<div class="surface empty-design"><p>${esc(e.message)}</p><button class="primary-button" id="reload-page">다시 시도</button></div>`;$('#reload-page').onclick=render;$('#main').removeAttribute('aria-busy');}
}
function accountHTML(){
 if(me)return heading('내 계정')+`<div class="surface login-card"><h2>${esc(me.name)}님, 반가워요.</h2><p>${me.email.endsWith('.invalid')?'소셜 로그인 계정':esc(me.email)}</p><p>${member.plan==='premium'?'Premium':'무료 회원'} · 전체곡 AAC 128kbps 감상</p><p>내 플레이리스트 ${member.owned_count} / ${member.playlist_limit}개 · ${member.full_lyrics?'전체 싱크 가사':'현재 가사 한 줄'}</p><p><a class="text-link" href="#membership">무료 · Premium 혜택 보기 →</a></p><p><a class="text-link" href="#gold">골드 · 보낸 선물 →</a></p>${authConfig?.admin?'<p><a class="text-link" href="#admin">정산 관리 →</a></p>':''}<div class="inline-actions"><a class="primary-button" href="#library">내 보관함</a><button class="small-button" id="logout">로그아웃</button></div></div>`;
 const error=location.hash.includes('?error=')?decodeURIComponent(location.hash.split('?error=')[1]):'';
 return `<section class="login-layout"><div class="login-story"><span class="eyebrow">AIFECT · AI + EFFECT</span><h1>새로운 취향의 시작.<br><em>마음껏, 무료로.</em></h1><p>회원이 되면 모든 곡을 끝까지 들을 수 있어요.<br>좋아하는 음악을 모으고 창작자와 이야기를 나눠보세요.</p><div class="login-perks"><span>${icon('play')} 전체곡 무료 스트리밍</span><span>${icon('heart')} 좋아요와 나만의 플레이리스트</span><span>${icon('users')} 아티스트 · 제작자 팔로우</span></div></div><div class="surface login-card"><span class="eyebrow">WELCOME TO AIFECT</span><h2 id="auth-title">이메일로 로그인</h2><p>새로운 음악이 기다리고 있어요.</p>${error?`<p class="form-error">${esc(error)}</p>`:''}<form id="auth-form" data-mode="login"><div id="signup-name" hidden>${formField('닉네임','name','text','','maxlength="40" autocomplete="nickname"')}</div>${formField('이메일','email','email','','required autocomplete="email"')}${formField('비밀번호','password','password','','required minlength="12" maxlength="128" autocomplete="current-password" placeholder="12자 이상"')}<button class="primary-button full-width" id="auth-submit">로그인</button><p class="form-error" role="alert"></p></form><button class="text-link auth-switch" id="auth-switch">처음 오셨나요? 무료 회원가입</button><div class="login-divider">소셜 계정으로 계속하기</div>${inApp&&authConfig.providers?.includes('google')?'<p class="login-note">앱에서는 Google 로그인을 준비 중이에요. 이메일 · 카카오 · Apple로 계속해주세요.</p>':''}${[['google','Google'],['kakao','카카오'],['apple','Apple']].filter(([p])=>!(inApp&&p==='google')).map(([p,n])=>authConfig.providers?.includes(p)?`<a class="social-login ${p}" href="/api/auth/${p}" data-oauth>${n}로 계속하기</a>`:`<button class="social-login ${p}" disabled>${n} · 연결 준비 중</button>`).join('')}<p class="login-note">회원은 모든 곡을 무료로 감상할 수 있습니다.</p><p class="policy-note"><a href="/terms" target="_blank" rel="noopener">이용약관</a> · <a href="/privacy" target="_blank" rel="noopener">개인정보처리방침</a> · <a href="/contact" target="_blank" rel="noopener">고객센터</a></p></div></section>`;
}
function playlistsHTML(items){return `<div class="playlist-grid">${items.map(p=>`<a class="playlist-card surface" href="#playlist/${p.id}"><div class="playlist-art cover-lime">${icon('list')}</div><h2>${esc(p.name)}</h2><p>${p.tracks}곡 · ${p.is_public?'공개':'비공개'}</p></a>`).join('')}</div>`;}
function commentsHTML(comments,t){
 const row=c=>`<article class="live-comment ${c.parent_id?'is-reply':''}"><div class="comment-avatar">${esc(c.name.slice(0,1))}</div><div><div><strong>${esc(c.name)}</strong>${c.creator?'<span class="creator-badge">PRODUCER</span>':''}<span class="comment-age">${new Date(c.created*1000).toLocaleDateString('ko-KR')}${c.edited?' · 수정됨':''}</span></div><p>${c.timestamp!==null?`<button class="timestamp" data-seek="${c.timestamp}" data-track="${t.id}">${time(c.timestamp)}</button>`:''}${esc(c.body)}</p><div class="inline-actions"><button class="text-link ${c.liked?'is-active':''}" data-comment-like="${c.id}" data-liked="${!!c.liked}">${icon('heart')} ${c.likes}</button>${!c.parent_id?`<button class="text-link" data-reply="${c.id}" data-track="${t.id}">답글</button>`:''}${me?.id===c.user_id?`<button class="text-link" data-edit-comment="${c.id}" data-body="${esc(c.body)}">수정</button><button class="text-link" data-delete-comment="${c.id}">삭제</button>`:''}</div></div></article>`;
 return comments.length?comments.filter(c=>!c.parent_id).map(c=>row(c)+comments.filter(r=>r.parent_id===c.id).map(row).join('')).join(''):'<p class="quiet">첫 감상을 남겨보세요.</p>';
}
function songCredits(t){return t.kind==='cover'?`<div class="song-credits"><div><span>COVER BY</span><a href="#producer/${t.producer_id}">${esc(t.producer)}</a></div><div><span>ORIGINAL</span><a href="#song/${t.original_id}">${esc(t.original_title)} · ${esc(t.original_artist)}</a></div></div>`:`<div class="song-credits"><div><span>AI ARTIST</span><a href="#artist/${t.artist_id}">${esc(t.artist)}</a></div><div><span>PRODUCER</span><a href="#producer/${t.producer_id}">${esc(t.producer)}</a></div></div>`;}
function coversPanelHTML(t,d,sort){if(!d)return '';const tabs=[['popular','좋아요순'],['gifts','선물순'],['plays','재생순'],['recent','최신순']];
 return `<section class="surface covers-panel"><div class="section-heading"><h2>커버곡 <small>${number(d.covers.length)}</small></h2>${d.accepts_covers?`<a class="small-button" href="#cover/${t.id}">${icon('plus')} 이 곡 커버 올리기</a>`:''}</div>${d.accepts_covers?`<a class="text-link cover-song-rank-link" href="#community/rankings?period=all&amp;original_id=${esc(t.id)}">${icon('chart')} 이 곡의 오늘 · 이달 · 역대 커버 랭킹 →</a>`:''}${d.covers.length?`<div class="tabs covers-sort">${tabs.map(([k,v])=>`<a class="tab ${sort===k?'active':''}" href="#song/${t.id}?covers=${k}">${v}</a>`).join('')}</div>${list(d.covers)}`:`<p class="empty-note">${d.accepts_covers?'아직 커버곡이 없어요. 첫 커버의 주인공이 되어보세요.':'원곡자가 커버를 허락하지 않은 곡이에요.'}</p>`}</section>`;}
function personProfileHTML(d,id,tab){const p=d.profile,items=tab==='covers'?d.covers:d.tracks;
 return `<section class="person-profile surface"><div class="profile-banner">${p.banner_version?`<img src="/media/banner/${esc(p.id)}?v=${esc(p.banner_version)}" alt="${esc(p.name)} 대표 이미지">`:''}</div><div class="person-profile-body">${portrait(p,'producer')}<div><h2>${esc(p.name)}</h2><p>${esc(p.bio||'새로운 음악으로 만나요.')}</p><div class="inline-actions"><span>${number(d.followers)} 팔로워 · 제작곡 ${d.tracks.length} · 커버곡 ${d.covers.length}</span><button class="primary-button" data-follow="producer/${id}">${followed('producer',id)?'팔로잉':'팔로우'}</button></div></div></div></section>`
 +`<div class="tabs">${[['tracks','제작곡',d.tracks.length],['covers','커버곡',d.covers.length]].map(([k,v,n])=>`<a class="tab ${tab===k?'active':''}" href="#producer/${id}?tab=${k}">${v} ${n}</a>`).join('')}</div>`
 +(items.length?list(items):`<p class="surface empty-note">${tab==='covers'?'아직 부른 커버곡이 없어요.':'아직 직접 만든 곡이 없어요.'}</p>`)
 +giftsPanelHTML(d.gifts,'선물 순위');}
function giftsPanelHTML(g,title){if(!g)return '';return `<section class="surface gift-rank"><div class="section-heading"><h2>${title}</h2>${g.total_gold?`<span>${number(g.total_gold)}골드</span>`:''}</div>${g.ranking.length?`<ol class="gift-ranking">${g.ranking.map(r=>`<li><b>${r.rank}</b><span>${esc(r.name)}</span><em>${number(r.gold)}골드</em></li>`).join('')}</ol>`:'<p>아직 받은 선물이 없어요. 첫 선물의 주인공이 되어보세요.</p>'}</section>`;}
function goldHTML(d){return heading('골드','창작자에게 마음을 전하는 선물이에요.')+`<section class="surface gold-card"><span class="eyebrow">보유 골드</span><strong class="gold-balance">${number(d.balance)}</strong><p>1골드 = ${d.gold_krw}원 (부가세 포함)</p></section>${section('골드 충전')}<div class="gold-packs">${d.packs.map(p=>`<div class="surface gold-pack"><strong>${number(p.gold)}골드</strong><span>${number(p.price)}원</span><button class="small-button" data-buy-gold="${p.gold}" ${d.checkout_available?'':'disabled'}>${d.checkout_available?'충전하기':'결제 준비 중'}</button></div>`).join('')}</div>${d.checkout_available?'':'<p class="field-help">골드 충전은 결제 준비가 끝나면 열려요. 결제 · 환불 규정도 그때 함께 안내드려요.</p>'}${section('보낸 선물')}${d.sent.length?`<div class="surface gift-history">${d.sent.map(g=>`<div class="gift-row"><a href="#song/${g.track_id}">${esc(g.title)}${g.kind==='cover'?' (커버)':''}</a><span>${number(g.gold)}골드</span><time>${new Date(g.created*1000).toLocaleDateString('ko-KR')}</time></div>`).join('')}</div>`:'<p class="surface empty-note">아직 보낸 선물이 없어요.</p>'}`;}
